<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {approveReturn,createReturn,getOrders,getReturns,submitReturn,type Order,type SalesReturn} from '@/services/business'
import {useAuthStore} from '@/stores/auth'

const auth=useAuthStore(),returns=ref<SalesReturn[]>([]),orders=ref<Order[]>([]),selectedOrder=ref(''),reason=ref('')
const quantities=ref<Record<string,number>>({}),dispositions=ref<Record<string,string>>({}),error=ref(''),notice=ref(''),busy=ref(false)
const page=ref(0),pages=ref(0),order=computed(()=>orders.value.find(item=>item.id===selectedOrder.value))

async function load(){const[result,orderResult]=await Promise.all([getReturns(page.value),getOrders()]);returns.value=result.items;pages.value=result.totalPages;orders.value=orderResult.filter(item=>['COMPLETED','PARTIALLY_RETURNED'].includes(item.status))}
async function move(value:number){page.value=value;await load()}
async function create(){if(!order.value)return;const items=order.value.items.filter(item=>(quantities.value[item.id]??0)>0).map(item=>({orderItemId:item.id,quantity:quantities.value[item.id],disposition:dispositions.value[item.id]??'RESTOCK'}));if(!items.length){error.value='Chọn ít nhất một dòng và nhập số lượng trả.';return}busy.value=true;error.value='';notice.value='';try{const created=await createReturn({orderId:order.value.id,reason:reason.value,items});notice.value=`Đã tạo ${created.returnNumber}.`;reason.value='';quantities.value={};page.value=0;await load()}catch{error.value='Không thể tạo phiếu trả. Kiểm tra số lượng còn được phép trả.'}finally{busy.value=false}}
async function action(id:string,kind:'submit'|'approve'){error.value='';try{kind==='submit'?await submitReturn(id):await approveReturn(id);await load()}catch{error.value=kind==='approve'?'Không thể duyệt. Người tạo không được tự duyệt và số tiền hoàn không được vượt tiền đã thu.':'Không thể gửi duyệt phiếu trả.'}}
onMounted(async()=>{try{await load()}catch{error.value='Không thể tải dữ liệu trả hàng.'}})
</script>

<template>
  <section class="p-6 lg:p-8">
    <p class="text-sm font-semibold text-cyan-700">Kiểm soát bán hàng</p><h2 class="text-3xl font-bold">Trả hàng & hoàn tiền</h2>
    <div v-if="auth.hasPermission('return.create')" class="mt-6 rounded-xl border bg-white p-5"><h3 class="font-bold">Tạo phiếu trả</h3><div class="mt-4 grid gap-3 md:grid-cols-2"><select v-model="selectedOrder" class="rounded-lg border p-3"><option value="">Chọn đơn đã hoàn tất</option><option v-for="item in orders" :key="item.id" :value="item.id">{{item.orderNumber}} · {{Number(item.total).toLocaleString()}} {{item.currency}}</option></select><input v-model="reason" minlength="3" maxlength="1000" class="rounded-lg border p-3" placeholder="Lý do trả hàng"></div><div v-if="order" class="mt-4 divide-y rounded-lg border"><div v-for="line in order.items" :key="line.id" class="grid items-center gap-3 p-3 md:grid-cols-[1fr_8rem_10rem]"><span><b>{{line.sku}}</b> · {{line.productName}} (đã mua {{line.quantity}})</span><input v-model.number="quantities[line.id]" type="number" min="0" :max="line.quantity" step="0.0001" class="rounded border p-2" placeholder="Số lượng"><select v-model="dispositions[line.id]" class="rounded border p-2"><option value="RESTOCK">Nhập lại kho</option><option value="DAMAGED">Hư hỏng</option><option value="QUARANTINE">Cách ly</option></select></div></div><button :disabled="busy||!selectedOrder||reason.length<3" class="mt-4 rounded-lg bg-cyan-700 px-4 py-2 font-semibold text-white disabled:opacity-50" @click="create">Tạo phiếu trả</button></div>
    <p v-if="error" class="mt-5 rounded-lg bg-red-50 p-4 text-red-800">{{error}}</p><p v-if="notice" class="mt-5 rounded-lg bg-emerald-50 p-4 text-emerald-800">{{notice}}</p>
    <div class="mt-6 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Phiếu</th><th class="p-4">Lý do</th><th class="p-4">Hoàn dự kiến</th><th class="p-4">Trạng thái</th><th class="p-4">Thao tác</th></tr></thead><tbody class="divide-y"><tr v-for="item in returns" :key="item.id"><td class="p-4 font-mono">{{item.returnNumber}}</td><td class="p-4">{{item.reason}}</td><td class="p-4">{{Number(item.refundTotal).toLocaleString()}} VND</td><td class="p-4"><StatusBadge :value="item.status" /><span v-if="item.refundStatus"> · <StatusBadge :value="item.refundStatus" /></span></td><td class="p-4"><button v-if="item.status==='DRAFT'&&auth.hasPermission('return.create')" class="text-cyan-700" @click="action(item.id,'submit')">Gửi duyệt</button><button v-if="item.status==='PENDING_APPROVAL'&&auth.hasPermission('return.approve')" class="text-cyan-700" @click="action(item.id,'approve')">Duyệt & hoàn tiền</button></td></tr><tr v-if="!returns.length"><td colspan="5" class="p-8 text-center text-slate-400">Không có phiếu trả hàng.</td></tr></tbody></table></div>
    <div class="mt-3 flex items-center justify-end gap-3 text-sm"><button :disabled="page===0" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="move(page-1)">Trước</button><span>Trang {{pages?page+1:0}} / {{pages}}</span><button :disabled="page+1>=pages" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="move(page+1)">Sau</button></div>
  </section>
</template>
